sources.separate.cod:
using symbol "std:io" @print;
using "a.cod" Sample;
using "a.cod" score as score_a;
using "b.cod" score as score_b;
using "a.cod" adapter_twice as twice_a;
using "b.cod" adapter_twice as twice_b;
using "core.cod" twice;
symbol @arena::region;
effect @arena <- region(1024u64);
{
  let sample = deref(alloc @arena Sample(0));
  behave @print(score_a(sample));
  behave @print(score_b(sample));
  behave @print(twice(sample));
  behave @print(twice_a(sample));
  behave @print(twice_b(sample));
};

